            records.append({
                "timestamp": time.time(),
                "cpu_usage": cpu_usage
            })
        except Exception:
            pass

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
        return os.path.abspath(LOGFILE_PATH)
    except IOError:
