PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'
def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    if not isinstance(python_version, str):
        raise TypeError("Python version must be a string")

    if path_to_append not in sys.path:
        sys.path.append(path_to_append)

    python_executable = f"python{python_version}"

    try:
        result = subprocess.check_output([python_executable, "--version"], stderr=subprocess.STDOUT)
        version_output = result.decode('utf-8').strip()

        if python_version in version_output:
            return python_version
        else:
            raise RuntimeError("Failed to verify the requested Python version")
    except (subprocess.CalledProcessError, FileNotFoundError):
        raise RuntimeError(f"Python version {python_version} not found or inaccessible")

